{"cmd": "cd /storage/emulated/0 && find . -maxdepth 1 -type f -printf '%s\t%f\n' 2>/dev/null | awk -F'\t' '{
  size=$1; name=$2;
  if (name ~ /\./) {
    ext = name; gsub(/.*\./, "", ext); ext = "." ext
  } else {
    ext = "(no extension)"
  }
  sizes[ext] += size; counts[ext]++; 
  if (size > max[ext] || max[ext] == "") max[ext] = size
  if (size > 1000000) { big_files = big_files "\n  " sprintf("%.1f MB", size/1048576) " - " name }
}
END {
  printf "=== FILES BY EXTENSION ===\n"
  for (ext in counts) {
    printf "%-20s %3d files  %10s total  (largest: %10s)\n", ext, counts[ext], human(sizes[ext]), human(max[ext])
  }
  printf "\n=== LARGE FILES (>1 MB) ===%s\n", big_files
  printf "\nTotal files: %d\n", total
}
function human(n) {
  if (n >= 1073741824) return sprintf("%.1f GB", n/1073741824)
  if (n >= 1048576) return sprintf("%.1f MB", n/1048576)
  if (n >= 1024) return sprintf("%.1f KB", n/1024)
  return n " B"
}'", "justification": "Categorize and count files by extension with size summaries"}
